def parse_ports(spec):
    ports = set()
    for part in spec.split(","):
        part = part.strip()
        if not part:
            continue
        if "-" in part:
            lo, hi = (int(x) for x in part.split("-", 1))
            if lo > hi:
                raise ValueError("bad range: " + part)
            ports.update(range(lo, hi + 1))
        else:
            ports.add(int(part))
    if any(not 1 <= p <= 65535 for p in ports):
        raise ValueError("port out of range")
    return sorted(ports)

blocks.check:
assert parse_ports("80,443,8000-8003") == [80, 443, 8000, 8001, 8002, 8003], "range and list should combine"
assert parse_ports("22,22,21") == [21, 22], "duplicates removed and sorted"
for bad in ["0", "70000", "9-3"]:
    try:
        parse_ports(bad)
    except ValueError:
        pass
    else:
        raise AssertionError("parse_ports(%r) should raise ValueError" % bad)

