#!/usr/bin/env python3
"""portscan.py - threaded TCP connect scanner for YOUR OWN machines.

Usage: portscan.py HOST [-p 1-1024] [--json] [--timeout 0.5] [--workers 100]
Exit status: 0 open ports found, 1 none found, 2 bad usage or refused target.
"""
import argparse
import ipaddress
import json
import socket
import sys
from concurrent.futures import ThreadPoolExecutor


def parse_ports(spec):
    """'80,443,8000-8003' -> [80, 443, 8000, 8001, 8002, 8003]"""
    ports = set()
    for part in spec.split(","):
        part = part.strip()
        if "-" in part:
            lo, hi = (int(x) for x in part.split("-", 1))
            ports.update(range(lo, hi + 1))
        elif part:
            ports.add(int(part))
    if not ports or min(ports) < 1 or max(ports) > 65535:
        raise ValueError("ports must be between 1 and 65535")
    return sorted(ports)


def allowed(address):
    ip = ipaddress.ip_address(address)
    return ip.is_loopback or ip.is_private or ip.is_link_local


def probe(address, port, timeout):
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        s.settimeout(timeout)
        return port if s.connect_ex((address, port)) == 0 else None


def main(argv=None):
    ap = argparse.ArgumentParser(description="TCP connect scan of your own host or LAN.")
    ap.add_argument("host")
    ap.add_argument("-p", "--ports", default="1-1024")
    ap.add_argument("--timeout", type=float, default=0.5)
    ap.add_argument("--workers", type=int, default=100)
    ap.add_argument("--json", action="store_true")
    args = ap.parse_args(argv)

    try:
        ports = parse_ports(args.ports)
        address = socket.getaddrinfo(args.host, None, socket.AF_INET, socket.SOCK_STREAM)[0][4][0]
    except (ValueError, socket.gaierror) as exc:
        print(f"portscan: {exc}", file=sys.stderr)
        return 2
    if not allowed(address):
        print(f"portscan: refusing {address}: not loopback or private. "
              "Scan only what you own or have permission to test.", file=sys.stderr)
        return 2

    with ThreadPoolExecutor(max_workers=args.workers) as pool:
        found = [p for p in pool.map(lambda p: probe(address, p, args.timeout), ports) if p]

    if args.json:
        print(json.dumps({"host": args.host, "address": address, "scanned": len(ports), "open": found}))
    else:
        print(f"Scanned {len(ports)} ports on {args.host} ({address})")
        for port in found:
            try:
                name = socket.getservbyport(port, "tcp")
            except OSError:
                name = "unknown"
            print(f"  {port:>5}/tcp  open  {name}")
        if not found:
            print("  no open ports found")
    return 0 if found else 1


if __name__ == "__main__":
    sys.exit(main())
